package com.smarthub.plus;
import android.content.*;import android.view.accessibility.AccessibilityNodeInfo;import java.util.*;
/** Only the selected, visible satellite subtitle row is observed; no remote keys are injected. */
final class NativeTrackInfo {
 static void observe(Context c,AccessibilityNodeInfo root,SatelliteState state){if(state.channelId.isEmpty())return;List<AccessibilityNodeInfo> lists=root.findAccessibilityNodeInfosByViewId(SatelliteUiParser.DEFAULT_PACKAGE+":id/subtitle_list");for(AccessibilityNodeInfo list:lists)try{if(list.isVisibleToUser()){String selected=find(list,0,new int[]{0});if(!selected.isEmpty()){String upper=selected.toUpperCase(Locale.ROOT);String format=upper.contains("DVB")?"DVB":upper.contains("TXT")||upper.contains("TTX")||upper.contains("TELETEXT")?"TXT":"";String language=language(selected);c.getSharedPreferences("smarthub",0).edit().putString("native_track_channel",CHMAXIntegration.identity(state)).putString("native_track_format",format).putString("native_track_language",language).putString("native_track_label",selected.substring(0,Math.min(160,selected.length()))).apply();}}}finally{list.recycle();}}
 private static String find(AccessibilityNodeInfo n,int depth,int[] count){if(depth>18||count[0]++>200||n.isPassword()||n.isEditable())return "";if(n.isVisibleToUser()&&(n.isChecked()||n.isSelected())){String text=text(n,0);if(!text.isEmpty())return text;}for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo child=n.getChild(i);if(child!=null)try{String s=find(child,depth+1,count);if(!s.isEmpty())return s;}finally{child.recycle();}}return "";}
 private static String text(AccessibilityNodeInfo n,int depth){if(depth>4)return "";StringBuilder s=new StringBuilder(n.getText()==null?"":n.getText().toString());for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo child=n.getChild(i);if(child!=null)try{s.append(' ').append(text(child,depth+1));}finally{child.recycle();}}return s.toString().replaceAll("\\s+"," ").trim();}
 static String language(String label){String s=label.toLowerCase(Locale.ROOT);String[][] values={{"ar","arabic|ara|العربية"},{"en","english|eng|الإنجليزية"},{"nl","dutch|nederlands|nld|dut"},{"no","norwegian|norsk|nor"},{"fr","french|français|fra|fre"},{"de","german|deutsch|deu|ger"},{"it","italian|italiano|ita"},{"es","spanish|español|spa"},{"tr","turkish|türkçe|tur"},{"pl","polish|polski|pol"}};for(String[] item:values)if(java.util.regex.Pattern.compile("(?iu)(?<![\\p{L}])(?:"+item[1]+ ")(?![\\p{L}])").matcher(s).find())return item[0];return "";}
 static String hint(Context c){SharedPreferences p=c.getSharedPreferences("smarthub",0);String manual=p.getString("native_source_language","");if(!manual.isEmpty())return manual;return CHMAXIntegration.identity(SatelliteState.read(c)).equals(p.getString("native_track_channel",""))?p.getString("native_track_language",""):"";}
}
